const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₱'+Number(n).toLocaleString('en-PH',{minimumFractionDigits:2});let user='Alex',page='Dashboard',current=null,tab='Overview',filter='All',emailTab='Inbox',emailPick=null,paused=false,draft=null;const nav=['Dashboard','Reimbursements','Auto-Updater','Email Center','Requirements Checker','Reports','Settings'];const icons=['⌂','▤','↻','✉','☑','▥','⚙'];let records=[],messages=[],runs=[];let settings={recipient:'claims@example.com',template:'Good day,\n\nPlease see the reviewed supporting documents for this reimbursement request.\n\nReference: {{id}}\nClient: {{name}}\nAmount: {{amount}}\n\nPlease acknowledge receipt. Thank you.'};
function makeRecord(n,name,status,owner='Alex'){return{id:'AMAPHIL-2026-'+String(n).padStart(5,'0'),name,status,owner,amount:8500,approved:0,date:'2026-10-02',facility:'Sample Medical Center',email:name.toLowerCase().replace(/ /g,'.')+'@example.com',docs:['Official receipt 01.jpg','Official receipt 02.jpg','Laboratory request.jpg','Itemized charges.pdf'].map((name,i)=>({name,reviewed:i!==1,selected:true,replace:false,size:[1.4,1.1,.8,.6][i]})),events:['Request imported from the sample Form.'],notes:[],proposal:null,followup:status==='Processing',closed:false};}
function seed(){records=[makeRecord(127,'Jamie Santos','New request'),makeRecord(126,'Morgan Cruz','New request','Sam'),makeRecord(125,'Casey Reyes','Lacking'),makeRecord(124,'Taylor Garcia','Processing'),makeRecord(123,'Jordan Lim','Processing','Sam'),makeRecord(122,'Riley Tan','Paid','Sam')];records[2].docs[3].replace=true;records[2].docs[3].reviewed=false;records[2].docs[3].selected=false;records[5].approved=8500;messages=[{id:1,caseId:records[3].id,owner:'Alex',direction:'Sent',subject:'Reimbursement Request | '+records[3].id,body:'Please review the attached supporting documents.',from:'alex.processor@example.com',to:settings.recipient,files:['Official receipt 01.jpg','Laboratory request.jpg'],date:'Oct 2, 9:32 AM',matched:true},{id:2,caseId:records[4].id,owner:'Sam',direction:'Inbox',subject:'Re: Reimbursement Request | '+records[4].id,body:'We have received your request and are reviewing the submitted documents.',from:settings.recipient,to:'sam.processor@example.com',files:[],date:'Oct 5, 10:24 AM',matched:true},{id:3,caseId:null,owner:'Alex',direction:'Inbox',subject:'Additional documents received',body:'Please confirm which reimbursement this message relates to.',from:settings.recipient,to:'alex.processor@example.com',files:[],date:'Oct 6, 8:10 AM',matched:false}];runs=[];draft=null;paused=false;}
seed();function badge(s){const colors={'New request':'new','Submitted':'submitted','Processing':'processing','Approved':'approved','Paid':'paid','Lacking':'lacking','Denied':'denied','Needs replacement':'lacking','Needs review':'review','Verified':'approved','Reviewed':'approved','Sent':'submitted','Inbox':'processing','Matched':'approved','Unmatched':'review'};return `<span class="badge status-${colors[s]||'neutral'}"><span class="statusdot" aria-hidden="true"></span>${esc(s)}</span>`;}
function unreadReply(r){return messages.some(m=>m.caseId===r.id&&m.direction==='Inbox'&&!m.read);}
function attention(r){if(['Paid','Denied'].includes(r.status))return null;if(r.proposal)return {label:'Decision to review',kind:'decision',tab:'Emails',action:'Read reply'};if(unreadReply(r))return {label:'New reply',kind:'reply',tab:'Emails',action:'Read reply'};if(r.status==='Lacking')return {label:'Missing documents',kind:'missing',tab:'Requirements',action:'View requirements'};if(r.status==='New request')return {label:r.docs.every(d=>d.reviewed&&!d.replace)?'Ready to send':'Review documents',kind:'new',tab:'Documents',action:'Review documents'};if(r.followup)return {label:'Follow-up due',kind:'followup',tab:'Emails',action:'View conversation'};return null;}
function attentionBadge(r){const a=attention(r);return a?`<span class="attention attention-${a.kind}"><span aria-hidden="true">${a.kind==='new'?'●':'!'}</span>${a.label}</span>`:'<span class="muted mini">No action needed</span>';}
function matchesFilter(r){return filter==='All'||(filter==='Needs attention'?!!attention(r):r.status===filter);}
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',4500);}function rec(){return records.find(r=>r.id===current);}function log(r,s){r.events.unshift(s);}function go(p){page=p;current=null;filter='All';render();}function openRecord(id,t='Overview'){current=id;tab=t;page='Reimbursements';if(t==='Emails')messages.filter(m=>m.caseId===id&&m.direction==='Inbox').forEach(m=>m.read=true);render();}function heading(title,desc,actions=''){return `<div class="heading"><div><h1>${title}</h1><p class="muted">${desc}</p></div><div class="row">${actions}</div></div>`;}function btn(text,fn,cls=''){return `<button class="${cls}" onclick="${fn}">${text}</button>`;}function tabs(items,active,fn){return `<div class="tabs">${items.map(x=>btn(x,`${fn}('${x}')`,x===active?'active':'')).join('')}</div>`;}function setTab(t){tab=t;if(t==='Emails')messages.filter(m=>m.caseId===current&&m.direction==='Inbox').forEach(m=>m.read=true);render();}function setFilter(f){filter=f;render();}function closeModal(){$('#modal').close();}function modal(html){$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}function modalHead(s){return `<div class="modalhead"><h2>${s}</h2>${btn('Close','closeModal()','quiet')}</div>`;}
function render(){ $('#nav').innerHTML=nav.map((n,i)=>`<button class="${page===n?'active':''}" onclick="go('${n}')"><span class="icon" aria-hidden="true">${icons[i]}</span>${n}</button>`).join('');$('#breadcrumb').textContent=current?'Reimbursements / '+current:page;const views={'Dashboard':dashboard,'Reimbursements':()=>current?detail():list(),'Auto-Updater':updater,'Email Center':emailCenter,'Requirements Checker':requirements,'Reports':reports,'Settings':settingsView,'Form':formView,'Compose':composer};$('#app').innerHTML=(views[page]||dashboard)();}
function table(rows){return `<div class="tablewrap"><table><thead><tr><th>Reference / client</th><th>Provider</th><th>Amount</th><th>Status</th><th>Attention</th><th>Next action</th></tr></thead><tbody>${rows.map(r=>{const a=attention(r);return `<tr class="${r.status==='New request'?'new-request-row':''}"><td>${btn(r.id,`openRecord('${r.id}')`,'textlink')}<br><small>${esc(r.name)}</small></td><td>AMAPHIL</td><td>${money(r.amount)}</td><td>${badge(r.status)}</td><td>${attentionBadge(r)}</td><td>${btn(a?a.action:'View record',`openRecord('${r.id}','${a?a.tab:'Overview'}')`,'textlink')}</td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">No matching reimbursements.</td></tr>'}</tbody></table></div>`;}
function dashboard(){const stats=[['New request','New requests'],['Lacking','Missing requirements'],['Processing','Processing'],['Paid','Paid']];return heading('Dashboard','Your shared reimbursement workspace.',btn('Simulate new submission',"page='Form';render()",'primary'))+`<div class="stats">${stats.map(([s,l])=>`<button class="stat stat-${s.toLowerCase().replace(/ /g,'-')}" onclick="page='Reimbursements';filter='${s}';current=null;render()"><span>${l}</span><strong>${records.filter(r=>r.status===s).length}</strong><em>View requests</em></button>`).join('')}</div><div class="grid"><section class="panel flush"><div class="toolbar row between"><h2>Needs attention <span class="attention-count">${records.filter(r=>attention(r)).length}</span></h2>${btn('View all',"go('Reimbursements')",'quiet')}</div>${table(records.filter(r=>attention(r)))}</section><div><section class="panel"><h3>Today’s follow-ups</h3>${records.filter(r=>r.followup).map(r=>`<div class="event"><strong>${esc(r.name)}</strong><p class="mini muted">${r.id}</p>${btn('View conversation',`openRecord('${r.id}','Emails')`,'textlink')}</div>`).join('')||'<p class="muted">No follow-ups due.</p>'}</section><section class="panel"><h3>Recent activity</h3>${records.slice(0,3).map(r=>`<div class="event"><span>${esc(r.events[0])}</span><small>${r.id}</small></div>`).join('')}</section></div></div><div class="note">Demo mode: all records, documents, accounts, messages, and connection indicators are simulated. Changes last until you reload or reset.</div>`;}
function list(){return heading('Reimbursements','View and manage reimbursement requests.',btn('New sample request',"page='Form';render()",'primary'))+tabs(['All','Needs attention','New request','Submitted','Processing','Approved','Paid','Lacking','Denied'],filter,'setFilter')+`<div class="filters"><input id="search" aria-label="Search name or reference" placeholder="Search by name or reference" oninput="searchRows(this.value)">${btn('Export CSV','exportCsv()')}</div><div class="panel flush" id="result">${table(records.filter(matchesFilter))}</div>`;}function searchRows(s){$('#result').innerHTML=table(records.filter(r=>matchesFilter(r)&&(r.name+' '+r.id).toLowerCase().includes(s.toLowerCase())));}
function detail(){const r=rec();return heading(esc(r.id),esc(r.name),badge(r.status)+attentionBadge(r)+btn('Back to list',"current=null;render()"))+tabs(['Overview','Documents','Requirements','Emails','History'],tab,'setTab')+(tab==='Overview'?overview(r):tab==='Documents'?documents(r):tab==='Requirements'?checklist(r):tab==='Emails'?caseEmails(r):history(r));}
function overview(r){return `<div class="threecol"><section class="panel"><h3>Client information</h3><dl class="kv"><dt>Full name</dt><dd>${esc(r.name)}</dd><dt>Email</dt><dd>${esc(r.email)}</dd><dt>Mobile</dt><dd>Sample number withheld</dd></dl></section><section class="panel"><h3>Reimbursement details</h3><dl class="kv"><dt>Provider</dt><dd>AMAPHIL</dd><dt>Type</dt><dd>Outpatient</dd><dt>Service date</dt><dd>${r.date}</dd><dt>Facility</dt><dd>${esc(r.facility)}</dd><dt>Claimed</dt><dd>${money(r.amount)}</dd><dt>Approved</dt><dd>${r.approved?money(r.approved):'Not confirmed'}</dd></dl></section><section class="panel"><h3>Actions</h3><div class="actions">${btn('Compose email','startCompose()','primary')}${btn('Update status','statusDialog()')}${btn('Add note','noteDialog()')}</div></section></div><section class="panel"><h3>Notes</h3>${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')||'<p class="muted">No notes yet.</p>'}</section>`;}function paper(d,small=false){return `<div class="paper ${small?'smallpaper':''}"><h3>${esc(d.name.replace(/\.(jpg|pdf)$/,''))}</h3><div class="watermark">FICTIONAL DOCUMENT · DEMO</div><hr><div class="paperline"><span>Client</span><span>Sample Client</span></div><div class="paperline"><span>Date</span><span>02 Oct 2026</span></div><div class="paperline"><span>Consultation</span><span>₱1,500</span></div><div class="paperline"><span>Laboratory</span><span>₱2,750</span></div><hr><div class="paperline"><strong>Total</strong><strong>₱4,250</strong></div><p class="watermark">Not valid for reimbursement</p></div>`;}
function documents(r){return `<div class="row between" style="margin-bottom:16px"><div><h2>Supporting documents (${r.docs.length})</h2><small>Review each file, then choose which attachments to send.</small></div>${btn('Prepare email','startCompose()','primary')}</div><div class="docs">${r.docs.map((d,i)=>`<article class="doc"><div class="doctop"><button class="preview" aria-label="Preview ${esc(d.name)}" onclick="previewDoc(${i})">${paper(d,true)}</button></div><div class="docbody"><strong>${esc(d.name)}</strong><small>${d.size} MB · ${d.name.endsWith('pdf')?'PDF':'Image'}</small><p style="margin:8px 0">${badge(d.replace?'Needs replacement':d.reviewed?'Reviewed':'Needs review')}</p><label class="check"><input type="checkbox" ${d.selected?'checked':''} ${d.replace?'disabled':''} onchange="selectDoc(${i},this.checked)">Include in email</label><div class="docactions">${btn('Inspect',`previewDoc(${i})`)} ${d.replace?btn('Simulate replacement',`replaceDoc(${i})`):''}</div></div></article>`).join('')}</div>`;}function selectDoc(i,v){rec().docs[i].selected=v;}function previewDoc(i){const d=rec().docs[i];modal(modalHead(esc(d.name))+paper(d)+`<div class="actions">${btn('Enlarge',"document.querySelector('#modal .paper').classList.toggle('enlarged')")}${btn('Mark reviewed',`reviewDoc(${i})`,'primary')}${btn('Needs replacement',`flagDoc(${i})`)}</div><p class="muted mini" style="margin-top:12px">Illustrative sample preview. No actual medical documents are loaded.</p>`);}function reviewDoc(i){const r=rec(),d=r.docs[i];d.reviewed=true;d.replace=false;log(r,user+' reviewed '+d.name+'.');closeModal();render();notify('Document marked reviewed.');}function flagDoc(i){const r=rec(),d=r.docs[i];d.reviewed=false;d.replace=true;d.selected=false;r.status='Lacking';log(r,'Replacement requested: '+d.name);closeModal();render();}function replaceDoc(i){const d=rec().docs[i];d.replace=false;d.reviewed=false;log(rec(),'Sample replacement received for '+d.name);render();notify('Replacement received. Review it before sending.');}
function checklist(r){return `<div class="panel"><h3>Requirements checklist</h3><p class="muted small">File presence and document approval are tracked separately.</p>${r.docs.map((d,i)=>`<div class="row between" style="padding:15px 0;border-bottom:1px solid var(--line)"><div><strong>${esc(d.name)}</strong><br>${badge(d.replace?'Needs replacement':d.reviewed?'Verified':'Needs review')}</div><div class="row">${btn('Inspect',`previewDoc(${i})`)}${d.replace?btn('Simulate replacement',`replaceDoc(${i})`):''}</div></div>`).join('')}<div class="actions">${btn('Request missing documents',"startCompose('requirements')",'primary')}${btn('Review documents',"setTab('Documents')")}</div></div>`;}
function history(r){return `<section class="panel"><h3>Activity history</h3>${r.events.map(e=>`<div class="event">${esc(e)}<small>Prototype activity</small></div>`).join('')}</section>`;}
function messageHTML(m){return `<article class="email"><div class="emailhead"><strong>${esc(m.subject)}</strong>${badge(m.direction)}</div><small>From: ${esc(m.from)}<br>To: ${esc(m.to)} · ${esc(m.date)} · ${esc(m.owner)}’s mailbox</small><p>${esc(m.body)}</p>${m.files.map(f=>`<span class="attachment">${esc(f)}</span>`).join('')}</article>`;}
function caseEmails(r){messages.filter(m=>m.caseId===r.id&&m.direction==='Inbox').forEach(m=>m.read=true);return `<div class="row between" style="margin-bottom:17px"><h2>Conversation</h2><div class="row">${btn('Compose email','startCompose()','primary')}${btn('Simulate reply','replyDialog()')}${btn(r.followup?'Snooze follow-up':'Set follow-up','followup()')}</div></div>${r.proposal?`<div class="note orange-note"><strong>Status suggestion: ${r.proposal.status}</strong><p>Review the reply before confirming this change${r.proposal.amount?' to '+money(r.proposal.amount):''}.</p>${btn('Confirm update','confirmProposal()','primary')} ${btn('Dismiss suggestion',"rec().proposal=null;render()")}</div>`:''}${messages.filter(m=>m.caseId===r.id).map(messageHTML).join('')||'<div class="panel empty">No messages yet. Review the documents and compose the first email.</div>'}`;}
function startCompose(purpose='submission'){const r=rec();if(!r)return;draft={caseId:r.id,purpose,owner:user,to:settings.recipient,cc:'',subject:(purpose==='requirements'?'Additional requirements':'Reimbursement Request')+' | '+r.id,body:purpose==='requirements'?'Good day,\n\nPlease provide or replace the following documents for '+r.id+':\n'+r.docs.filter(d=>!d.reviewed||d.replace).map(d=>'- '+d.name).join('\n')+'\n\nThank you.':settings.template.replace('{{id}}',r.id).replace('{{name}}',r.name).replace('{{amount}}',money(r.amount)),saved:false};if(purpose==='requirements')r.docs.forEach(d=>d.selected=false);page='Compose';render();}
function composer(){const r=records.find(r=>r.id===draft.caseId);current=r.id;const chosen=r.docs.filter(d=>d.selected);return heading('Compose email','Review the message and attachments before sending.',btn('Back to record',`openRecord('${r.id}','Documents')`))+`<div class="note">Sending as ${esc(user.toLowerCase())}.processor@example.com · Simulated Gmail account</div><div class="grid"><section class="panel"><label>Email template<select onchange="loadTemplate(this.value)"><option value="submission" ${draft.purpose==='submission'?'selected':''}>Reimbursement request</option><option value="requirements" ${draft.purpose==='requirements'?'selected':''}>Missing requirements</option><option value="followup" ${draft.purpose==='followup'?'selected':''}>Follow-up</option></select></label><label>To<input id="to" value="${esc(draft.to)}" oninput="draft.to=this.value"></label><label>CC<input id="cc" value="${esc(draft.cc)}" placeholder="Optional email address" oninput="draft.cc=this.value"></label><label>Subject<input id="subject" value="${esc(draft.subject)}" oninput="draft.subject=this.value"></label><label>Message<textarea id="body" oninput="draft.body=this.value">${esc(draft.body)}</textarea></label><div class="actions">${btn('Save draft','saveDraft()')}${btn('Preview email','previewEmail()')}${btn('Simulate send','sendEmail()','primary')}</div><p id="senderror" role="alert" class="danger" style="margin-top:13px"></p></section><section class="panel"><h3>Attachments from the Form</h3><p class="small muted">${chosen.length} selected · ${chosen.reduce((s,d)=>s+d.size,0).toFixed(1)} MB</p>${r.docs.map((d,i)=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><label class="check"><input type="checkbox" ${d.selected?'checked':''} ${d.replace?'disabled':''} onchange="selectDoc(${i},this.checked);render()">${esc(d.name)}</label><div class="row between" style="margin-top:8px">${badge(d.replace?'Needs replacement':d.reviewed?'Reviewed':'Needs review')}${btn('Inspect',`previewDoc(${i})`,'quiet')}</div></div>`).join('')}<p class="small muted" style="margin-top:16px">Only checked files are included. Selected documents must be reviewed.</p></section></div>`;}
function loadTemplate(p){draft.purpose=p;draft.subject=(p==='followup'?'Follow-up':p==='requirements'?'Additional requirements':'Reimbursement Request')+' | '+rec().id;draft.body=p==='followup'?'Good day,\n\nMay we request an update on '+rec().id+'?\n\nThank you.':p==='requirements'?'Good day,\n\nPlease provide the missing or corrected documents for '+rec().id+'.\n\nThank you.':settings.template.replace('{{id}}',rec().id).replace('{{name}}',rec().name).replace('{{amount}}',money(rec().amount));render();}function saveDraft(){draft.saved=true;draft.owner=user;notify('Demo draft saved. Find it under Email Center / Drafts.');}function previewEmail(){modal(modalHead('Email preview')+messageHTML({subject:draft.subject,from:user.toLowerCase()+'.processor@example.com',to:draft.to,direction:'Draft',body:draft.body,date:'Not sent',owner:user,files:rec().docs.filter(d=>d.selected).map(d=>d.name)}));}
function sendEmail(){const r=rec(),docs=r.docs.filter(d=>d.selected);let error='';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.to.trim()))error='Enter a valid recipient address.';else if(draft.cc&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.cc.trim()))error='Enter one valid CC address, or leave CC blank.';else if(!draft.subject.includes(r.id))error='Keep the reimbursement reference in the subject.';else if(!draft.body.trim())error='Add a message.';else if(docs.some(d=>!d.reviewed||d.replace))error='Review each selected attachment before sending.';else if(draft.purpose==='submission'&&r.docs.some(d=>!d.reviewed||d.replace))error='Complete all required document reviews before the initial submission.';else if(draft.purpose==='submission'&&!docs.length)error='Select supporting documents for the initial submission.';if(error){$('#senderror').textContent=error;return false;}messages.unshift({id:Date.now(),caseId:r.id,owner:user,direction:'Sent',subject:draft.subject,body:draft.body,from:user.toLowerCase()+'.processor@example.com',to:draft.to+(draft.cc?' (CC: '+draft.cc+')':''),files:docs.map(d=>d.name),date:'Just now',matched:true});if(draft.purpose==='submission')r.status='Submitted';r.followup=true;log(r,user+' sent a simulated '+draft.purpose+' email with '+docs.length+' attachments.');draft=null;openRecord(r.id,'Emails');notify('Demo email sent. No real email left this prototype.');return true;}
function replyDialog(){const r=rec();modal(modalHead('Simulate an incoming reply')+`<p class="muted">Create a sample reply linked to ${r.id}.</p><label>Reply type<select id="replytype"><option value="received">Request received</option><option value="approved">Approved</option><option value="lacking">Additional documents needed</option><option value="denied">Denied</option></select></label>${btn('Add sample reply','simulateReply()','primary')}`);}function simulateReply(){const r=rec(),type=$('#replytype').value;const replyOwner=messages.find(m=>m.caseId===r.id&&m.direction==='Sent')?.owner||r.owner;const status={received:'Processing',approved:'Approved',lacking:'Lacking',denied:'Denied'}[type];const body={received:'We have received the documents and are processing this request.',approved:'Your reimbursement has been approved. Approved amount: '+money(r.amount)+'. Please wait for disbursement.',lacking:'Please provide a clearer copy of the official receipt before we continue.',denied:'This sample request has been denied. Please contact the department for clarification.'}[type];messages.unshift({id:Date.now(),caseId:r.id,owner:replyOwner,direction:'Inbox',subject:'Re: Reimbursement Request | '+r.id,body,from:settings.recipient,to:replyOwner.toLowerCase()+'.processor@example.com',date:'Just now',files:[],matched:true});if(type==='received'&&!['Paid','Approved','Denied'].includes(r.status)&&!paused){r.status=status;log(r,'Auto-Updater matched a receipt acknowledgement and set Processing.');}else{r.proposal={status,amount:type==='approved'?r.amount:0};log(r,'Incoming reply matched. '+status+' update awaits review.');}runs.unshift('Matched reply for '+r.id);closeModal();openRecord(r.id,'Emails');notify('Sample reply added to '+replyOwner+'’s mailbox.');}function confirmProposal(){const r=rec();if(!r.proposal)return;r.status=r.proposal.status;r.approved=r.proposal.amount||r.approved;log(r,user+' confirmed '+r.status+' after reviewing the reply.');r.proposal=null;render();}function followup(){const r=rec();r.followup=!r.followup;log(r,r.followup?'Follow-up scheduled.':'Follow-up snoozed in the demo.');render();notify(r.followup?'Follow-up added.':'Follow-up snoozed.');}
function statusDialog(){modal(modalHead('Update reimbursement status')+`<label>Status<select id="newstatus">${['New request','Lacking','Submitted','Processing','Approved','Paid','Denied'].map(s=>`<option ${rec().status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Reason or evidence<textarea id="reason" placeholder="Explain the update"></textarea></label>${btn('Save status','saveStatus()','primary')}<p id="statuserror" class="danger"></p>`);}function saveStatus(){const why=$('#reason').value.trim();if(!why){$('#statuserror').textContent='Add a reason to preserve the history.';return;}const r=rec(),s=$('#newstatus').value;log(r,user+' changed '+r.status+' to '+s+': '+why);r.status=s;if(['Approved','Paid'].includes(s))r.approved=r.amount;if(['Paid','Denied'].includes(s))r.followup=false;closeModal();render();}function noteDialog(){modal(modalHead('Add a note')+'<label>Note<textarea id="newnote"></textarea></label>'+btn('Save note','saveNote()','primary'));}function saveNote(){const n=$('#newnote').value.trim();if(!n)return;rec().notes.unshift(user+': '+n);log(rec(),user+' added a note.');closeModal();render();}
function emailCenter(){let ms=messages.filter(m=>m.owner===user&&(emailTab==='Unmatched'?!m.matched:emailTab==='Sent'?m.direction==='Sent':m.direction==='Inbox'&&m.matched));const picked=ms.find(m=>m.id===emailPick)||ms[0];return heading('Email Center','Demo mailbox: '+user.toLowerCase()+'.processor@example.com')+tabs(['Inbox','Sent','Drafts','Unmatched','Templates'],emailTab,'setEmailTab')+(emailTab==='Drafts'?`<section class="panel">${draft&&draft.saved&&draft.owner===user?`<h3>${esc(draft.subject)}</h3>${btn('Open draft',"page='Compose';current=draft.caseId;render()",'primary')}`:'No saved draft for this user.'}</section>`:emailTab==='Templates'?`<section class="panel"><h3>Reimbursement request</h3><p style="white-space:pre-wrap">${esc(settings.template)}</p>${btn('Edit templates',"go('Settings')")}</section>`:`<div class="splitmail"><section class="panel flush">${ms.map(m=>`<button class="mailitem ${picked.id===m.id?'active':''}" onclick="emailPick=${m.id};render()"><strong>${esc(m.subject)}</strong><small>${esc(m.from)} · ${m.date}</small>${badge(m.matched?'Matched':'Unmatched')}</button>`).join('')||'<div class="empty">No messages in this view.</div>'}</section><section>${picked?messageHTML(picked)+(picked.caseId?btn('Open reimbursement',`openRecord('${picked.caseId}','Emails')`,'primary'):btn('Match to a reimbursement',`matchDialog(${picked.id})`,'primary')):'<div class="panel empty">Choose a message to read it.</div>'}</section></div>`);}function setEmailTab(t){emailTab=t;emailPick=null;render();}function matchDialog(id){modal(modalHead('Match message')+`<label>Reimbursement<select id="matchid">${records.map(r=>`<option value="${r.id}">${r.id} · ${esc(r.name)}</option>`).join('')}</select></label>${btn('Confirm match',`matchMessage(${id})`,'primary')}`);}function matchMessage(id){const m=messages.find(m=>m.id===id);m.caseId=$('#matchid').value;m.matched=true;log(records.find(r=>r.id===m.caseId),user+' manually linked a message.');closeModal();render();notify('Message linked without changing the reimbursement status.');}
function updater(){return heading('Auto-Updater','Simulate matching replies and tracking changes.',btn(paused?'Resume simulation':'Pause simulation','paused=!paused;render()',paused?'primary':''))+`<div class="note">Automation is ${paused?'paused':'enabled'} in this demo. Acknowledgements can update Processing; financial decisions require confirmation.</div><div class="panel"><h3>Simulate incoming email</h3><label>Reimbursement<select id="simcase">${records.map(r=>`<option value="${r.id}">${r.id} · ${esc(r.name)}</option>`).join('')}</select></label>${btn('Choose reply scenario',"current=document.querySelector('#simcase').value;replyDialog()",'primary')}</div><section class="panel"><h3>Pending review</h3>${records.filter(r=>r.proposal).map(r=>`<div class="row between" style="padding:12px 0"><span>${esc(r.name)} · ${r.proposal.status}</span>${btn('Review evidence',`openRecord('${r.id}','Emails')`)}</div>`).join('')||'<p class="muted">No status suggestions awaiting review.</p>'}</section><section class="panel"><h3>Simulation log</h3>${runs.map(s=>`<div class="event">${esc(s)}</div>`).join('')||'<p class="muted">No simulated runs yet.</p>'}</section>`;}
function requirements(){return heading('Requirements Checker','Find incomplete or unreviewed supporting documents.')+`<section class="panel flush">${table(records.filter(r=>r.docs.some(d=>!d.reviewed||d.replace)))}</section>`;}
function reports(){return heading('Reports','Totals calculated from the current demo records.',btn('Export CSV','exportCsv()'))+`<div class="stats"><div class="stat"><span>Requests</span><strong>${records.length}</strong></div><div class="stat"><span>Total claimed</span><strong style="font-size:1.4rem">${money(records.reduce((s,r)=>s+r.amount,0))}</strong></div><div class="stat"><span>Total approved</span><strong style="font-size:1.4rem">${money(records.reduce((s,r)=>s+r.approved,0))}</strong></div><div class="stat"><span>Paid cases</span><strong>${records.filter(r=>r.status==='Paid').length}</strong></div></div><div class="panel flush">${table(records)}</div>`;}function exportCsv(){const cell=v=>'"'+String(v).replace(/"/g,'""')+'"';const csv=[['Reference','Client','Provider','Claimed','Approved','Status'],...records.map(r=>[r.id,r.name,'AMAPHIL',r.amount,r.approved,r.status])].map(a=>a.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='RMC2-demo-reimbursements.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Exported sample records only.');}
function settingsView(){return heading('Settings','Demo recipients, templates, and connection previews.')+`<div class="twocol"><section class="panel"><h3>Department recipients</h3><label>AMAPHIL email<input id="setting-to" value="${esc(settings.recipient)}"></label><label>Default message<textarea id="setting-template">${esc(settings.template)}</textarea></label><small>Available fields: {{id}}, {{name}}, {{amount}}</small><div class="actions">${btn('Save demo settings','saveSettings()','primary')}</div></section><section class="panel"><h3>Connections</h3>${['Google Form','Master Google Sheet','Supporting documents','Alex’s Gmail','Sam’s Gmail'].map(x=>`<div class="row between" style="padding:13px 0;border-bottom:1px solid var(--line)"><span>${x}</span>${badge('Demo only')}</div>`).join('')}<p class="muted small" style="margin-top:15px">No Google account is connected. Switching the demo user changes the simulated sending mailbox.</p></section></div>`;}function saveSettings(){const v=$('#setting-to').value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)){notify('Enter a valid demo recipient.');return;}settings.recipient=v;settings.template=$('#setting-template').value;notify('Demo settings saved for this session.');}
function formView(){return heading('Simulate a Google Form submission','Create a fictional request and see it enter the monitoring queue.',btn('Back to dashboard',"go('Dashboard')"))+`<form class="panel formwidth" id="sampleform"><div class="twocol"><label>Client name<input name="name" value="Avery Flores" required></label><label>Email<input name="email" type="email" value="avery@example.com" required></label><label>Provider<select><option>AMAPHIL</option></select></label><label>Service date<input type="date" name="date" value="2026-10-06" required></label><label>Facility<input name="facility" value="Sample Medical Center" required></label><label>Claimed amount<input name="amount" type="number" min="1" step="0.01" value="6200" required></label></div><h3>Supporting documents</h3><p class="muted small">Four fictional document previews will be attached automatically.</p><div class="flow"><span>Receipt 01</span><span>Receipt 02</span><span>Laboratory request</span><span>Itemized charges</span></div><button type="submit" class="primary">Submit sample request</button></form>`;}
document.addEventListener('submit',e=>{if(e.target.id!=='sampleform')return;e.preventDefault();const f=new FormData(e.target);const next=Math.max(...records.map(r=>Number(r.id.split('-').pop())))+1;const r=makeRecord(next,f.get('name'),'New request',user);r.email=f.get('email');r.amount=Number(f.get('amount'));r.facility=f.get('facility');r.date=f.get('date');r.docs.forEach(d=>d.reviewed=false);records.unshift(r);openRecord(r.id,'Documents');notify('New sample request created with 4 documents.');});$('#user').onchange=e=>{user=e.target.value;if(page==='Compose'&&draft){draft.owner=user;}render();notify('Switched to '+user+'’s simulated account.');};$('#reset').onclick=()=>modal(modalHead('Reset prototype?')+'<p>This clears only this session’s simulated changes.</p>'+btn('Reset demo',"seed();current=null;page='Dashboard';closeModal();render();notify('Demo reset.')",'primary'));render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_reimbursement',description:'Open a fictional reimbursement in this prototype.',inputSchema:{type:'object',properties:{reference:{type:'string'}},required:['reference'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({reference})=>{if(!records.some(r=>r.id===reference))throw new Error('Unknown sample reference');openRecord(reference);return{reference,screen:'Overview'};}});}catch(e){console.warn('Optional browser tool unavailable');}}
